ass="todo-flower__center" cx="24" cy="24" r="11"/></svg>@else<span class="todo-check__empty" aria-hidden="true"></span>@endif</button></form><div class="min-w-0 flex-1"><p class="font-semibold text-indigo-950 {{ $todo->is_completed?'line-through opacity-60':'' }}">{{ $todo->title }}</p><div class="mt-2 flex flex-wrap gap-2 text-xs text-stone-500">@if($todo->due_date)<span>{{ $todo->due_date->format('Y/n/j') }} {{ $todo->due_time?substr($todo->due_time,0,5):'' }}</span>@endif @if($todo->project)<span>{{ $todo->project->name }}</span>@endif<span class="today-priority today-priority--{{ $todo->priority }}">優先度 {{ $labels[$todo->priority] }}</span>@if($todo->recurrence!=='none')<span>繰り返し</span>@endif</div>@if($todo->memo)<p class="mt-2 whitespace-pre-line text-sm text-stone-600">{{ $todo->memo }}</p>@endif</div><div class="flex shrink-0 gap-1"><a href="{{ route('todos.edit',$todo) }}" class="text-action">編集</a><form method="POST" action="{{ route('todos.destroy',$todo) }}" onsubmit="return confirm('削除しますか？')">@csrf @method('DELETE')<button class="text-action text-red-600">削除</button></form></div></li>@endforeach</ul>@endif</x-site-app>





